  if (moveX || moveY) { const v = norm(moveX, moveY); p.x = clamp(p.x + v.x * p.speed * dt, 28, W - 28); p.y = clamp(p.y + v.y * p.speed * dt, 28, H - 28); p.angle = Math.atan2(v.y, v.x); }
